import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"레퍼런스 게임 조사 — 무엇을 누구에게서 빌렸나","description":"","frontmatter":{},"headers":[],"relativePath":"design/Game-References.md","filePath":"design/Game-References.md"}'),l={name:"design/Game-References.md"};function o(i,t,h,n,s,f){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="레퍼런스-게임-조사-—-무엇을-누구에게서-빌렸나" tabindex="-1">레퍼런스 게임 조사 — 무엇을 누구에게서 빌렸나 <a class="header-anchor" href="#레퍼런스-게임-조사-—-무엇을-누구에게서-빌렸나" aria-label="Permalink to &quot;레퍼런스 게임 조사 — 무엇을 누구에게서 빌렸나&quot;">​</a></h1><p>이 게임의 설계는 실존하는 15개 이상의 전략·전술 RPG를 역분해한 결과 위에 서 있다. 2026-09-07 소유자 결정으로 목표 형태가 <strong>4X + RPG, 실시간 진형·카드 전투</strong>로 재규정됐다. 이에 따라 Songs of Silence가 목표 형태의 기준 레퍼런스로, 라벨렌 전기가 턴제 SRPG 쪽의 마지막 정밀 참조로 추가됐다. 이 페이지가 정리하는 것은 두 가지다. 각 레퍼런스에서 어떤 요소를 차용했고 그것이 어떤 시스템으로 조합되었는지, 그리고 의도적으로 가져오지 않은 것이 무엇인지다. 상세 조사 원문은 저장소 내부 <code>docs/game-logic/reference/</code> 디렉터리(16종·출처 514개 이상)에 영구 보관되어 있으며, 각 항목은 <code>[REF:게임-메커니즘]</code> 형식으로 추적할 수 있다.</p><blockquote><p>이 페이지의 잔선 적용은 설계 방향과 구현 제안이다. 여섯 프리셋, 16국 전략 지도, 포획·영입, 지속 부상 등이 현재 런타임에 모두 구현되었다는 뜻이 아니다. 현재 완료 상태는 개발 로드맵과 저장소 ToDo.md를 확인한다.</p></blockquote><h2 id="차용-원칙" tabindex="-1">차용 원칙 <a class="header-anchor" href="#차용-원칙" aria-label="Permalink to &quot;차용 원칙&quot;">​</a></h2><ol><li>모든 차용은 원문 출처와 함께 기록한다 — 추측으로 채우지 않는다.</li><li>여러 게임이 같은 문제에 다른 해법을 제시하면 선택지로 병기하고 잔선의 선택 이유를 명시한다.</li><li>가져오지 않은 것도 명시한다 — 부정확한 연상을 막는다.</li></ol><h2 id="대출-매트릭스" tabindex="-1">대출 매트릭스 <a class="header-anchor" href="#대출-매트릭스" aria-label="Permalink to &quot;대출 매트릭스&quot;">​</a></h2><table tabindex="0"><thead><tr><th>레퍼런스</th><th>차용한 요소</th><th>잔선에서의 형태</th><th>의도</th></tr></thead><tbody><tr><td><strong>K-시스템</strong> (내부 별칭)</td><td>결핍의 종류가 난이도</td><td>6종 시작 프리셋</td><td>반복 플레이의 출발점 다양화</td></tr><tr><td></td><td>정착은 선택적 승급</td><td>떠돌이 → 시설 이용권 → 선택적 역 운영자</td><td>정착 없이도 성장 루프 완결</td></tr><tr><td></td><td>회복 가능한 실패</td><td>쓰러짐 ≠ 사망, 부상은 인물에 남는다</td><td>실패 후 재기</td></tr><tr><td></td><td>세계 상태 전이</td><td>핵심 인물 생존·수감 → 지역 변화</td><td>제한된 세계 반응</td></tr><tr><td><strong>배틀 브라더즈</strong></td><td>시간 = 비용</td><td>이동·휴식만 캠페인 시간 진행, 보급 일일 소모</td><td>날수까지 계산하는 운영</td></tr><tr><td></td><td>로스터 ≠ 배치</td><td>로스터 6 · 배치 상한 3 · 부상자 교체 휴식</td><td>인원 관리 의사결정</td></tr><tr><td></td><td>지형 비용</td><td>오르막 +1AP, 고지 사거리 +1</td><td>하이트맵 전술 가치</td></tr><tr><td></td><td>세계 위기</td><td>중반 세계 이벤트 → 물가·고용 변화</td><td>세계가 살아있음을 경제로 체감</td></tr><tr><td><strong>크루세이더 킹즈 3</strong></td><td>선택 투명성</td><td>조우 3선택 비용·효과·위험 사전 공개</td><td>추측이 아니라 계산</td></tr><tr><td></td><td>인물 존재감</td><td>초상·관계·상태 상시 표시, 경고 배지</td><td>인물이 자원</td></tr><tr><td></td><td>지도 정보 모드</td><td>전략 노선도의 세력권·통행권 전환</td><td>같은 지도의 다른 질문</td></tr><tr><td><strong>파이어 엠블렘·FFT</strong></td><td>유닛→명령→대상→확정/취소</td><td>이동·공격·대기 + 공격 예상 + 무소모 취소</td><td>실수 없는 수동 전술</td></tr><tr><td></td><td>고도·전투 시간 분리</td><td>하이트맵 B1/B2, 전투 행동시간은 월드와 다름</td><td>층구분·시간 규칙</td></tr><tr><td><strong>창세기전·트라이앵글</strong></td><td>인터미션</td><td>거점 허브 (비지도 관리면)</td><td>준비·장비·대화의 원조</td></tr><tr><td></td><td>선택이 관계에 누적</td><td>조우 선택 → 관계·평판 누적</td><td>행동의 지속적 결과</td></tr><tr><td><strong>유니콘 오버로드</strong></td><td>리더가 이동을 결정</td><td>파티 편성·대표 토큰</td><td>최강 개인 ≠ 최적 리더</td></tr><tr><td><strong>배너로드</strong></td><td>클랜 티어 → 정치 자격</td><td>밴드 평판 → 시설 접근 → 역 운영권</td><td>성장이 곧 권한 확장</td></tr><tr><td><strong>신장의야망·삼국지</strong></td><td>영토 내정</td><td>역 시설 수리·운영 (후반)</td><td>정착 이후 심화 관리</td></tr><tr><td><strong>태합입지전</strong></td><td>생업 = 성장 경로</td><td>수리·의료·운송·교섭도 전투만큼 성장</td><td>전투만이 답이 아님</td></tr><tr><td><strong>XCOM 2</strong></td><td>양층 시간 압박</td><td>전략(보급 고갈) × 전술(턴 제한)</td><td>선공적 운영이 유일한 방어</td></tr><tr><td><strong>다키스트 던전</strong></td><td>소모품 같은 영웅</td><td>부상자 관리·로테이션 강제</td><td>마모가 난이도의 원천</td></tr><tr><td><strong>인투 더 브리치</strong></td><td>예고된 위협</td><td>위협 칸 표시, 적 의도 사전 공개</td><td>계산 가능한 전술</td></tr><tr><td><strong>Songs of Silence</strong></td><td>지도 턴 + 실시간 자동 전투 두 층</td><td>전략·여행은 확정 명령, 전투는 실시간 틱 시뮬레이션(일시정지 가능)</td><td>목표 형태 자체</td></tr><tr><td></td><td>전투 전 배치 = 주 입력</td><td>진형 편집(전열·후열·측면, 4방향 정면)</td><td>유닛 마이크로 없는 전술</td></tr><tr><td></td><td>영웅·장소가 부여하는 카드</td><td>인물 카드(관계·생업·특기) + 거점 카드(보급·통행권·설비)</td><td>덱 구축 없는 부여형 카드</td></tr><tr><td></td><td>두 수치(HP·파워) + 특성</td><td>전투 판정 수치 압축 후보</td><td>스탯 줄 대신 특성 조합</td></tr><tr><td><strong>라벨렌 전기</strong></td><td>사기 60/40/80/0 + 항복 3조건</td><td>실시간 사기 게이지, 사기·지휘관 HP·퇴로가 맞으면 항복</td><td>궐주 대신 항복 → 포획·영입</td></tr><tr><td></td><td>지휘조·지휘 범위</td><td>진형 리더의 지휘 반경 안에서만 카드·협공</td><td>진형이 지휘의 단위</td></tr><tr><td></td><td>인연 5유형 × 등급 C/B/A</td><td>관계 등급이 카드 효과를 정하는 관계 카드</td><td>인물 쌍이 전술 자원</td></tr><tr><td></td><td>병참 준비안 최대 2·출격 시 차감</td><td>출격 전 거점 카드 슬롯 2</td><td>보급이 전장에 들어오는 길</td></tr></tbody></table><h2 id="일곱-차원-종합" tabindex="-1">일곱 차원 종합 <a class="header-anchor" href="#일곱-차원-종합" aria-label="Permalink to &quot;일곱 차원 종합&quot;">​</a></h2><p>교차 종합 보고서(CROSS-GAME-SYNTHESIS.md, 내부)가 각 차원에서 최고 모델을 선정한 결과:</p><table tabindex="0"><thead><tr><th>차원</th><th>최고 모델</th><th>잔선 권고</th></tr></thead><tbody><tr><td>무에서 시작</td><td>K-시스템</td><td>결핍의 종류를 축으로 시작 설계 — 밴드 3인 + 손수레 + 3일 식량</td></tr><tr><td>경제 압박 루프</td><td>배틀 브라더즈</td><td>확정한 이동·휴식만 시간 진행 — 식량 + 수당 + 회복의 3중 압박</td></tr><tr><td>사망·부상 처리</td><td>배틀 브라더즈 + K-시스템</td><td>회복 가능한 실패 — 쓰러짐 ≠ 사망, 부상은 정산 영수증에 표시</td></tr><tr><td>전략↔전술 연결</td><td>배틀 브라더즈 / FFT</td><td>세 지도를 다른 질문·시간·통제권으로 분리</td></tr><tr><td>세계 진화</td><td>K-시스템 + 배틀 브라더즈</td><td>핵심 인물 상태 전이 + 지역 상황 변화의 두 속도</td></tr><tr><td>난이도 철학</td><td>트라이앵글 + FE</td><td>무레벨스케일링 + 실패 시 진척 보존 병용</td></tr><tr><td>포획·모집</td><td>K-시스템 + 배틀 브라더즈</td><td>구조→신뢰→가입의 관계 기반 — 즉시 구매 없음</td></tr></tbody></table><h2 id="세-표면-구조" tabindex="-1">세 표면 구조 <a class="header-anchor" href="#세-표면-구조" aria-label="Permalink to &quot;세 표면 구조&quot;">​</a></h2><p>장르 조사가 확정한 핵심: 지도는 크기가 아니라 플레이어의 동사로 구별한다.</p><table tabindex="0"><thead><tr><th>표면</th><th>질문</th><th>형태</th><th>차용</th></tr></thead><tbody><tr><td><strong>S 전략 노선도</strong></td><td>누가 어디를 지배하며 무엇을 우선할 것인가?</td><td>서울 전체 → 16국 세력권 · 2D 평면 도식</td><td>CK3 정보 모드, 신장·삼국지 영토</td></tr><tr><td><strong>W 역간 여행</strong></td><td>일행은 어디로, 어떤 대가로 갈 것인가?</td><td>현재역→목적역 · 경로·보급·사건</td><td>FFT 이동일, 배틀 브라더즈 지속 비용</td></tr><tr><td><strong>B 전투 하이트맵</strong></td><td>지금 누가 어느 칸에서 무엇을 할 것인가?</td><td>역 내부 B1/B2 · 사각 칸 · 고저차</td><td>FE·FFT 전술, BB 지형, ITB 위협 표시</td></tr><tr><td>N 비지도 관리면</td><td>누구를 준비시키고 무엇을 정산할 것인가?</td><td>인터미션·조우·배치·정산</td><td>창세기전 인터미션, CK3 이벤트</td></tr></tbody></table><h2 id="시작-프리셋" tabindex="-1">시작 프리셋 <a class="header-anchor" href="#시작-프리셋" aria-label="Permalink to &quot;시작 프리셋&quot;">​</a></h2><p>결핍의 종류가 난이도를 만든다 — 숫자 조정이 아니라 &quot;무엇이 없는가&quot;가 다르다. 자세한 수치는 <code>Starting-Presets.md</code> 참조.</p><table tabindex="0"><thead><tr><th>프리셋</th><th>난이도</th><th>핵심 결핍</th><th>장기 규칙</th></tr></thead><tbody><tr><td>떠돌이 삼인조</td><td>★★</td><td>거점·보급</td><td>없음 (표준)</td></tr><tr><td>전직 자치 순찰대</td><td>★</td><td>관계 (배신자 취급)</td><td>신도림 자치회 회복이 첫 관문</td></tr><tr><td>상인 잔존자</td><td>★★</td><td>전투력</td><td>교역 이윤 +20% / 전투원 비용 +50%</td></tr><tr><td>탈영 소대</td><td>★★★★</td><td>광역 적대</td><td>추격자 주기 스폰</td></tr><tr><td>고아 무리</td><td>★★★★★</td><td>모든 것</td><td>성장 ×2 / 사기 타격 ×2 / 보상 −30%</td></tr><tr><td>마지막 역장</td><td>★★</td><td>역 책임</td><td>영등포 부분 통제 · 상실 시 망명 (게임오버 아님)</td></tr></tbody></table><h2 id="의도적으로-가져오지-않은-것" tabindex="-1">의도적으로 가져오지 않은 것 <a class="header-anchor" href="#의도적으로-가져오지-않은-것" aria-label="Permalink to &quot;의도적으로 가져오지 않은 것&quot;">​</a></h2><ul><li>CK3식 전투 추상화·봉건 계승 — 격자 위의 실시간 진형 전투가 이 게임의 계약이므로</li><li>FE·FFT·라벨렌의 턴·페이즈·되감기·유닛 단위 명령 — 2026-09-07부로 전투는 실시간 진형·카드이므로(예측 표시·무소모 취소의 투명성 원칙은 진형 편집과 카드 예측로 이어간다)</li><li>Songs of Silence의 카드 랜덤 드로우·카드 부활 경제 — 투명성과 부상 이행 계약과 충돌하므로</li><li>배틀 브라더즈의 육각 격자·9AP·대규모 용병단 수치 — 사각 3AP·소수 파티 유지</li><li>K-시스템의 초반 반복 노동 — 흥미 곡선 보호</li><li>FE식 자동 원상복구 — 부상 이행이 계약이므로</li><li>전면 시뮬레이션형 4X — 4X 골격(탐사·확장·개발·정복)은 채택하되, 제한된 상태 전이로 인과를 읽을 수 있게 유지(Songs of Silence식 경량 4X에 가까움)</li></ul><h2 id="포획과-영입" tabindex="-1">포획과 영입 <a class="header-anchor" href="#포획과-영입" aria-label="Permalink to &quot;포획과 영입&quot;">​</a></h2><p>전투에서 적 대표를 생포하면 심문·인도·고용 협상 중 선택한다. 모집은 세 경로로 분리된다: 구조→신뢰→가입(핵심 동료) / 계약 인력(유료·기간제) / 역 내 인력 시장. 즉시 돈으로 사는 핵심 동료는 없다 — 관계가 게이트다.</p><h2 id="상세-백과사전-위키-페이지" tabindex="-1">상세 백과사전 (위키 페이지) <a class="header-anchor" href="#상세-백과사전-위키-페이지" aria-label="Permalink to &quot;상세 백과사전 (위키 페이지)&quot;">​</a></h2><p>각 게임의 전체 메커니즘은 다음 위키 페이지에서 열람할 수 있다:</p><ul><li><a href="/rules/Ref-Mechanism-Index.html">차용 메커니즘 총람</a> — [REF:] 인용 체계 전체</li><li><a href="/rules/Ref-Cross-Synthesis.html">교차 종합 매트릭스</a> — 7차원 비교와 잔선 권고</li><li><a href="/rules/Ref-K-System.html">K-시스템</a> — 떠돌이 생존·정착 진행 (13 시작·33 능력·전투 공식)</li><li><a href="/rules/Ref-Battle-Brothers.html">배틀 브라더즈</a> — 용병회사 경제 (특전 50개·위기 4종)</li><li><a href="/rules/Ref-Crusader-Kings-3.html">크루세이더 킹즈 3</a> — 인물 중심 대전략 (계승·왕조·전쟁)</li><li><a href="/rules/Ref-Fire-Emblem-FFT.html">파이어 엠블렘·FFT</a> — 전술 전투 문법 (직업 20개·CT·궁합)</li><li><a href="/rules/Ref-Farland-Wog-Triangle.html">파랜드·창세기전·트라이앵글</a> — 한국·일본 SRPG (인터미션·신념·투표)</li><li><a href="/rules/Ref-Unicorn-Overlord.html">유니콘 오버로드</a> — 부대 편성 SRPG (명성·Tactics 프로그래밍)</li><li><a href="/rules/Ref-Bannerlord.html">배너로드</a> — 샌드박스 왕국 (클랜 티어·군단·공성)</li><li><a href="/rules/Ref-Nobunagas-Ambition.html">신장의야망</a> — 코에이 대전략 (내정·행동력·전투)</li><li><a href="/rules/Ref-Taikou-Risshiden.html">태합입지전</a> — 라이프시물레이션 (생업·직위·운영권)</li><li><a href="/rules/Ref-Three-Kingdoms.html">삼국지</a> — 코에이 대전략 (내정·병참·색칠·외교)</li><li><a href="/rules/Ref-XCOM-2.html">XCOM 2</a> — 양층 시간 압박 (전략 doom timer × 전술 턴제한)</li><li><a href="/rules/Ref-Darkest-Dungeon.html">다키스트 던전</a> — 마모 철학 (스트레스 2중HP·괴벽·광원)</li><li><a href="/rules/Ref-Into-The-Breach.html">인투 더 브리치</a> — 완전 정보 전술 (적 의도 예고·무확률 설계)</li><li><a href="/rules/Ref-Songs-of-Silence.html">Songs of Silence</a> — 목표 형태: 지도 턴 4X + 실시간 자동 전투 + 영웅 카드 (2026-09-07 추가)</li><li><a href="/rules/Ref-Ravelen-Chronicles.html">라벨렌 전기</a> — 한국어 웹 SRPG 역설계: 사기·항복·지휘조·인연·병참·전투 공식 (2026-09-07 추가)</li></ul>',23)])])}const u=d(l,[["render",o]]);export{g as __pageData,u as default};
